from pathlib import Path
import re
raw=Path('work/expected_report_pairs.tabular').read_text().splitlines()[1:]
# group by peptide preserving first appearance, collect distinct raw prot preserving order
pep_order=[]; group={}
for line in raw:
 p,prot=line.split('\\t',1)
 if p not in group:
  group[p]=[]; pep_order.append(p)
 if prot not in group[p]: group[p].append(prot)
out=[]
for p in pep_order:
 for prot in group[p]:
  # workflow filters in order: split ;, regex, split comma
  for item in prot.split(';'):
   item=re.sub(r'(tr|sp)[|]','',item)
   item=re.sub(r'[ ]+','',item)
   item=re.sub(r'[|].*"'$'"','',item)
   for sub in item.split(','):
    if sub: out.append((p,sub))
# dedup pairs preserving order (would query distinct in final only not relevant; do preserve)
seen=set(); uniq=[]
for pair in out:
 if pair not in seen: seen.add(pair); uniq.append(pair)
Path('work/group_normalized_pairs.tsv').write_text(''.join(f'{p}\\t{pid}\\n' for p,pid in uniq))
# compare to expected_normalized_pairs
exp=Path('work/expected_normalized_pairs.tsv').read_text().splitlines()
print('same count',len(uniq),len(exp))
for i,(a,b) in enumerate(zip(uniq,exp)):
 if a[0]+'\\t'+a[1]"'!=b:
  print('"'first diff',i,a,b);break
else:
 print('identical order' if len(uniq)==len(exp) else 'prefix same')
PY"

